begin;
create extension if not exists pgtap with schema extensions;
set search_path to public, extensions;
select plan(33);
insert into auth.users(id,instance_id,aud,role,email,encrypted_password,created_at,updated_at) values
('18310000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000000','authenticated','authenticated','mcp183-confirm@example.invalid','x',now(),now());
insert into public.organizations(id,name) values ('18310000-0000-0000-0000-000000000002','Synthetic');
insert into public.organization_members(organization_id,user_id,role) values ('18310000-0000-0000-0000-000000000002','18310000-0000-0000-0000-000000000001','owner');
insert into auth.oauth_clients(id,registration_type,redirect_uris,grant_types,client_type,token_endpoint_auth_method) values ('18310000-0000-0000-0000-000000000003','dynamic','http://localhost/callback','authorization_code','public','none');
insert into auth.oauth_consents(id,user_id,client_id,scopes) values ('18310000-0000-0000-0000-000000000004','18310000-0000-0000-0000-000000000001','18310000-0000-0000-0000-000000000003','openid');
insert into private.mcp_reauth_proofs(user_id,client_id,consent_granted_at,verified_at) select user_id,client_id,granted_at,clock_timestamp() from auth.oauth_consents where id='18310000-0000-0000-0000-000000000004';
insert into auth.sessions(id,user_id,oauth_client_id,created_at) values ('18310000-0000-0000-0000-000000000005','18310000-0000-0000-0000-000000000001','18310000-0000-0000-0000-000000000003',now());
insert into public.user_session_activity(session_hash,auth_session_id,user_id,last_activity,absolute_expires_at) values ('mcp183-browser','mcp183-browser','18310000-0000-0000-0000-000000000001',now(),now()+interval '1 hour');
insert into public.clients(id,organization_id,name) values ('18310000-0000-0000-0000-000000000006','18310000-0000-0000-0000-000000000002','Synthetic client');
insert into public.form_templates(client_id,schema) values ('18310000-0000-0000-0000-000000000006','[{"id":"note","label":"Note","type":"text"}]');
insert into public.reports(id,client_id,helper_id,service_date,status,start_at,end_at) values ('18310000-0000-0000-0000-000000000007','18310000-0000-0000-0000-000000000006','18310000-0000-0000-0000-000000000001','2026-10-28','pending','2026-10-28 01:00+00','2026-10-28 02:00+00');
insert into public.report_values(report_id,data) values ('18310000-0000-0000-0000-000000000007','{"note":"before"}');
insert into private.mcp_record_read_controls(organization_id,enabled,conditions,confirmed_by,confirmed_at) values ('18310000-0000-0000-0000-000000000002',true,'{}','18310000-0000-0000-0000-000000000001',now());
insert into private.mcp_record_edit_controls(organization_id,enabled,conditions,confirmed_by,confirmed_at) values ('18310000-0000-0000-0000-000000000002',true,'{}','18310000-0000-0000-0000-000000000001',now());
select set_config('request.jwt.claims','{"sub":"18310000-0000-0000-0000-000000000001","role":"mcp_import","exp":4102444800,"client_id":"18310000-0000-0000-0000-000000000003","session_id":"18310000-0000-0000-0000-000000000005"}',true);
insert into private.mcp_report_transition_controls(organization_id,enabled,conditions,confirmed_by,confirmed_at) values ('18310000-0000-0000-0000-000000000002',true,'{}','18310000-0000-0000-0000-000000000001',now());
select ok(not has_function_privilege('authenticated','private.review_mcp_report_transition(uuid,boolean)','execute'),'browser cannot directly invoke internal review');
savepoint disabled_prepare;
update private.mcp_report_transition_controls set enabled=false where organization_id='18310000-0000-0000-0000-000000000002';
select throws_ok($$select private.prepare_mcp_report_transition('18310000-0000-0000-0000-000000000002','18310000-0000-0000-0000-000000000007',0,'approve',null)$$,'42501','proposal_unavailable','disabled control rejects proposal');
rollback to savepoint disabled_prepare;
create temp table proposal_id as select private.prepare_mcp_report_transition('18310000-0000-0000-0000-000000000002','18310000-0000-0000-0000-000000000007',(select current_version from public.reports where id='18310000-0000-0000-0000-000000000007'),'approve',null) as id;
select is(public.get_mcp_report_transition_result('18310000-0000-0000-0000-000000000002',(select id from proposal_id))->>'status','confirmation_required','MCP can query the pending result');
select throws_ok($$select public.prepare_mcp_report_transition('18310000-0000-0000-0000-000000000002','18310000-0000-0000-0000-000000000007',0,'remand',null)$$,'22023','invalid_report_transition','remand requires a reason');
select throws_ok($$select public.prepare_mcp_report_transition('18310000-0000-0000-0000-000000000002','18310000-0000-0000-0000-000000000007',0,'approve','reason')$$,'22023','invalid_report_transition','approval rejects a reason');
select throws_ok($$select public.prepare_mcp_report_transition('18310000-0000-0000-0000-000000000002','18310000-0000-0000-0000-000000000007',999,'approve',null)$$,'22023','proposal_changed','proposal rejects a stale version');
select ok(not has_function_privilege('mcp_import','private.review_mcp_report_transition(uuid,boolean)','execute'),'MCP cannot directly confirm');
select throws_ok($$select private.review_mcp_report_transition((select id from proposal_id),true)$$,'42501','proposal_unavailable','OAuth cannot confirm');
select is((select status from public.reports where id='18310000-0000-0000-0000-000000000007'),'pending','proposal does not change report');
select set_config('request.jwt.claims','{"sub":"18310000-0000-0000-0000-000000000001","role":"authenticated","session_id":"mcp183-browser"}',true);
select is(private.review_mcp_report_transition((select id from proposal_id),false)->>'status','confirmation_required','browser can review proposal');
savepoint revoked;
update auth.oauth_consents set revoked_at=clock_timestamp() where id='18310000-0000-0000-0000-000000000004';
select throws_ok($$select private.review_mcp_report_transition((select id from proposal_id),true)$$,'42501','proposal_unavailable','revoked connection rejects confirmation');
rollback to savepoint revoked;
savepoint no_permission;
update public.organization_members set role='member' where organization_id='18310000-0000-0000-0000-000000000002' and user_id='18310000-0000-0000-0000-000000000001';
select throws_ok($$select private.review_mcp_report_transition((select id from proposal_id),true)$$,'42501','proposal_unavailable','lost permission rejects confirmation');
rollback to savepoint no_permission;
savepoint stale;
update public.report_values set data='{"note":"changed"}' where report_id='18310000-0000-0000-0000-000000000007';
select throws_ok($$select private.review_mcp_report_transition((select id from proposal_id),true)$$,'22023','proposal_changed','changed content rejects confirmation');
rollback to savepoint stale;
savepoint expired;
update private.mcp_report_transition_proposals set created_at=statement_timestamp()-interval '11 minutes',expires_at=statement_timestamp()-interval '2 minutes' where id=(select id from proposal_id);
select throws_ok($$select private.review_mcp_report_transition((select id from proposal_id),true)$$,'22023','proposal_expired','expired proposal cannot be confirmed');
rollback to savepoint expired;
savepoint audit_failure;
create function public.mcp183_fail_audit() returns trigger language plpgsql set search_path='' as $$
begin if new.action_type='report.mcp_transition.confirm' then raise exception 'fixture_audit_failed'; end if; return new; end $$;
create trigger mcp183_fail_audit before insert on public.audit_events for each row execute function public.mcp183_fail_audit();
select throws_ok($$select private.review_mcp_report_transition((select id from proposal_id),true)$$,'P0001','fixture_audit_failed','audit failure rejects confirmation');
select is((select status from public.reports where id='18310000-0000-0000-0000-000000000007'),'pending','audit failure rolls back approval');
select is((select count(*)::int from private.mcp_report_status_epochs where report_id='18310000-0000-0000-0000-000000000007'),0,'audit failure rolls back the status epoch');
rollback to savepoint audit_failure;
select is(private.review_mcp_report_transition((select id from proposal_id),true)->>'status','approved','approval succeeds');
select is((private.review_mcp_report_transition((select id from proposal_id),true)->>'replayed')::boolean,true,'approval replay returns prior result');
select is((select count(*)::int from public.audit_events where action_type='report.mcp_transition.confirm'),1,'replay does not duplicate audit');
select set_config('request.jwt.claims','{"sub":"18310000-0000-0000-0000-000000000001","role":"mcp_import","exp":4102444800,"client_id":"18310000-0000-0000-0000-000000000003","session_id":"18310000-0000-0000-0000-000000000005"}',true);
select is(public.get_mcp_report_transition_result('18310000-0000-0000-0000-000000000002',(select id from proposal_id))->>'status','approved','MCP can query the confirmed result');
create temp table remand_id as select private.prepare_mcp_report_transition('18310000-0000-0000-0000-000000000002','18310000-0000-0000-0000-000000000007',(select current_version from public.reports where id='18310000-0000-0000-0000-000000000007'),'remand','Synthetic reason') as id;
select set_config('request.jwt.claims','{"sub":"18310000-0000-0000-0000-000000000001","role":"authenticated","session_id":"mcp183-browser"}',true);
select is(private.review_mcp_report_transition((select id from remand_id),false)->>'reason','Synthetic reason','review shows remand reason');
savepoint stopped;
update private.mcp_report_transition_controls set enabled=false where organization_id='18310000-0000-0000-0000-000000000002';
select throws_ok($$select private.review_mcp_report_transition((select id from remand_id),true)$$,'42501','proposal_unavailable','disabled control rejects confirmation');
rollback to savepoint stopped;
select is(private.review_mcp_report_transition((select id from remand_id),true)->>'status','remanded','remand succeeds');
select is((select status from public.reports where id='18310000-0000-0000-0000-000000000007'),'remanded','remand changes status');
select is((select reason from private.mcp_report_transition_proposals where id=(select id from remand_id)),'Synthetic reason','remand reason retained');
select is(public.get_mcp_report_remand_reason('18310000-0000-0000-0000-000000000002','18310000-0000-0000-0000-000000000007'),'Synthetic reason','authorized user sees current remand reason');
select ok(not has_function_privilege('mcp_import','public.confirm_mcp_report_transition(uuid)','execute'),'MCP cannot invoke browser confirmation RPC');
select ok(not has_function_privilege('authenticated','public.prepare_mcp_report_transition(uuid,uuid,bigint,text,text)','execute'),'browser cannot invoke MCP preparation RPC');
select ok(not has_function_privilege('mcp_import','public.get_mcp_report_remand_reason(uuid,uuid)','execute'),'MCP cannot invoke browser reason RPC');
savepoint new_revision;
update public.reports set current_version=current_version+1 where id='18310000-0000-0000-0000-000000000007';
select is(public.get_mcp_report_remand_reason('18310000-0000-0000-0000-000000000002','18310000-0000-0000-0000-000000000007'),'Synthetic reason','reason remains visible after a content revision');
rollback to savepoint new_revision;
savepoint new_remand;
update public.reports set status='approved' where id='18310000-0000-0000-0000-000000000007';
update public.reports set status='remanded' where id='18310000-0000-0000-0000-000000000007';
select is(public.get_mcp_report_remand_reason('18310000-0000-0000-0000-000000000002','18310000-0000-0000-0000-000000000007'),null::text,'an unrelated later remand cannot show the earlier reason');
rollback to savepoint new_remand;
select set_config('request.jwt.claims','{"sub":"18310000-0000-0000-0000-000000000001","role":"mcp_import","exp":4102444800,"client_id":"18310000-0000-0000-0000-000000000003","session_id":"18310000-0000-0000-0000-000000000005"}',true);
select throws_ok($$select public.get_mcp_report_remand_reason('18310000-0000-0000-0000-000000000002','18310000-0000-0000-0000-000000000007')$$,'42501','permission_denied','OAuth role cannot read browser reason');
select * from finish();
rollback;
